#include "physics/vehicle.hpp"
#include <algorithm>
#include <bit>
#include <cmath>
#include <stdexcept>
namespace kartgib::physics {
static bool finite(double x){return std::isfinite(x);}
double clamp(double x,double lo,double hi){return std::max(lo,std::min(x,hi));}
bool valid(const Config& c){return c.mass>0&&c.wheelbase>0&&c.maxSteer>0&&c.maxSteer<1.5&&c.engineForce>=0&&c.brakeForce>=0&&c.drag>=0&&c.rolling>=0&&c.lateralGrip>=0&&c.suspensionK>=0&&c.suspensionD>=0&&c.restHeight>0&&c.wheelRadius>0&&c.boostCapacity>=0&&c.boostRegen>=0&&c.maxSpeed>0&&finite(c.mass)&&finite(c.wheelbase)&&finite(c.maxSpeed);}
Input sanitize(Input i){i.throttle=finite(i.throttle)?clamp(i.throttle,-1,1):0;i.brake=finite(i.brake)?clamp(i.brake,0,1):0;i.steer=finite(i.steer)?clamp(i.steer,-1,1):0;return i;}
Vec3 forward(double yaw){return {std::sin(yaw),0,std::cos(yaw)};}
Vec3 right(double yaw){return {std::cos(yaw),0,-std::sin(yaw)};}
double stoppingDistance(double speed,const Config& c,double friction){return speed*speed*c.mass/(2*std::max(1e-6,c.brakeForce*std::max(0.0,friction)));}
double steeringYawRate(double speed,double steer,const Config& c){return speed*std::tan(clamp(steer,-1,1)*c.maxSteer)/c.wheelbase;}
double suspensionForce(double compression,double rate,const Config& c){return std::max(0.0,c.suspensionK*compression+c.suspensionD*rate);}
Contact sphereAabb(Vec3 p,double r,AABB b){if(!(r>0))return {};Vec3 q{clamp(p.x,b.min.x,b.max.x),clamp(p.y,b.min.y,b.max.y),clamp(p.z,b.min.z,b.max.z)};Vec3 d{p.x-q.x,p.y-q.y,p.z-q.z};double l=std::sqrt(d.x*d.x+d.y*d.y+d.z*d.z);if(l>=r)return {};if(l>1e-9)return {true,{d.x/l,d.y/l,d.z/l},r-l};double distances[6]={p.x-b.min.x,b.max.x-p.x,p.y-b.min.y,b.max.y-p.y,p.z-b.min.z,b.max.z-p.z};int axis=int(std::min_element(distances,distances+6)-distances);Vec3 n{};if(axis<2)n.x=axis==0?-1:1;else if(axis<4)n.y=axis==2?-1:1;else n.z=axis==4?-1:1;return {true,n,r+distances[axis]};}
void resolveContact(State& s,const Contact& c){if(!c.hit||c.penetration<=0)return;s.position.x+=c.normal.x*c.penetration;s.position.y+=c.normal.y*c.penetration;s.position.z+=c.normal.z*c.penetration;Vec3 f=forward(s.yaw),r=right(s.yaw);double nf=f.x*c.normal.x+f.z*c.normal.z,nr=r.x*c.normal.x+r.z*c.normal.z;if(s.forwardSpeed*nf<0)s.forwardSpeed*=std::max(0.0,1-nf*nf);if(s.lateralSpeed*nr<0)s.lateralSpeed*=std::max(0.0,1-nr*nr);if(c.normal.y>0.5){s.verticalSpeed=std::max(0.0,s.verticalSpeed);s.grounded=true;}}
WheelPose wheelPose(const State& s,const Config& c,int idx){if(idx<0||idx>=4)throw std::out_of_range("wheelIndex");double z=(idx<2?0.5:-0.5)*c.wheelbase,x=(idx%2==0?-0.5:0.5)*1.2;Vec3 f=forward(s.yaw),r=right(s.yaw);return {{s.position.x+r.x*x+f.x*z,s.position.y-c.restHeight+c.wheelRadius,s.position.z+r.z*x+f.z*z},idx<2?0.0:0.0,s.forwardSpeed/c.wheelRadius*double(s.tick)/60.0,clamp(c.restHeight-s.height,0,c.restHeight)};}
Telemetry step(State& s,Input raw,const Config& c,Surface surface,double dt){if(!valid(c)||!finite(dt)||dt<=0||dt>0.1)throw std::invalid_argument("invalid vehicle config or timestep");Input in=sanitize(raw);double friction=clamp(finite(surface.friction)?surface.friction:1,0.05,2);double oldSpeed=s.forwardSpeed,oldLateral=s.lateralSpeed;double boost=0;if(in.boost&&s.boostEnergy>0&&in.throttle>0){boost=std::min(dt,s.boostEnergy);s.boostEnergy-=boost;}else s.boostEnergy=std::min(c.boostCapacity,s.boostEnergy+c.boostRegen*dt);double traction=c.engineForce*in.throttle+c.boostForce*(boost/dt);double brake=c.brakeForce*in.brake*friction;double resistance=c.drag*s.forwardSpeed*std::abs(s.forwardSpeed)+c.rolling*s.forwardSpeed;double net=traction-resistance;if(brake>0){double stop=std::abs(s.forwardSpeed)*c.mass/dt;net-=std::copysign(std::min(brake,stop),s.forwardSpeed==0?net:s.forwardSpeed);}s.forwardSpeed=clamp(s.forwardSpeed+net/c.mass*dt,-c.maxSpeed*0.35,c.maxSpeed);double yawRate=steeringYawRate(s.forwardSpeed,in.steer,c)*clamp(friction,0.1,1.5);s.yaw=std::remainder(s.yaw+yawRate*dt,6.283185307179586);s.lateralSpeed*=std::exp(-c.lateralGrip*friction*dt);Vec3 f=forward(s.yaw),r=right(s.yaw);s.position.x+=(f.x*s.forwardSpeed+r.x*s.lateralSpeed)*dt;s.position.z+=(f.z*s.forwardSpeed+r.z*s.lateralSpeed)*dt;double ground=finite(surface.height)?surface.height:0;double target=ground+c.restHeight;double compression=std::max(0.0,target-s.position.y);double spring=suspensionForce(compression,-s.verticalSpeed,c);s.verticalSpeed+=(spring/c.mass-9.81)*dt;s.position.y+=s.verticalSpeed*dt;if(s.position.y<target){s.position.y=target;s.verticalSpeed=std::max(0.0,s.verticalSpeed);s.grounded=true;}else s.grounded=false;s.height=s.position.y-ground;s.tick++;return {std::hypot(s.forwardSpeed,s.lateralSpeed),(s.forwardSpeed-oldSpeed)/dt,(s.lateralSpeed-oldLateral)/dt,spring,boost,false};}
void simulate(State& s,const std::vector<Input>& ins,const Config& c,Surface surface,double dt){for(auto i:ins)step(s,i,c,surface,dt);}
uint64_t fingerprint(const State& s){uint64_t h=1469598103934665603ULL;auto add=[&](double v){uint64_t x=std::bit_cast<uint64_t>(v);h=(h^x)*1099511628211ULL;};add(s.position.x);add(s.position.y);add(s.position.z);add(s.yaw);add(s.forwardSpeed);add(s.lateralSpeed);add(s.boostEnergy);h=(h^s.tick)*1099511628211ULL;return h;}
}
